def renderSiblings(quantity):
    # Use f-string for HTML formatting with dynamic content insertion
    html = f"<p>Based on {quantity} siblings:</p>"
    html += "<ul>"
    for **num_siblings in range(1, quantity+1)**:
        # Render odd-even logic directly into the list
        if render_sibling_info(num_siblings) == "Odd":
            html += f"<li>Sibling {num_siblings}</li>"
        else:
            html += f"<li>Sibling {num_siblings}</li>"
